import argparse
from datetime import datetime, timezone
import json
from pathlib import Path
import re


def time(s, tz=None):
    value = datetime.fromisoformat(s)
    if value.tzinfo is None:
        if tz is None:
            raise ValueError()
        value = value.replace(tzinfo=tz)
    return value


def summarize(root, now):
    boxes, bad, letters, seen = {}, [], [], set()
    paths = []
    for box in sorted(root.iterdir()):
        if not box.is_dir() or box.name.startswith('.'):
            continue
        if (box / 'inbox').is_dir():
            boxes[box.name] = dict(inbox={}, done=0)
            for where in ('inbox', 'done'):
                paths.extend(p for p in (box / 'inbox' / 'done' if where == 'done' else box / 'inbox').glob('*.md') if not p.name.startswith('.') and p.is_file() and not p.is_symlink())
    for p in sorted(paths, key=lambda p: p.relative_to(root).as_posix()):
        file = p.relative_to(root).as_posix()
        lines = p.read_text().splitlines()
        why = None
        if not lines or lines[0] != '---' or '---' not in lines[1:]:
            why = 'no_frontmatter'
        else:
            end = lines[1:].index('---') + 1
            data = dict(s.split(': ', 1) for s in lines[1:end] if ': ' in s)
            if any(not data.get(k) for k in ('id', 'from', 'to', 'status')):
                why = 'no_field'
            else:
                try:
                    at = time(data.get('at', ''), now.tzinfo)
                except ValueError:
                    why = 'no_field'
                if why is None:
                    try:
                        if not re.match(r'^\d{8}T\d{4}[-_]', p.name):
                            raise ValueError()
                        datetime.strptime(p.name[:13], '%Y%m%dT%H%M')
                    except ValueError:
                        why = 'bad_name'
                if why is None and data['id'] in seen:
                    why = 'dup_id'
        if why:
            bad.append(dict(file=file, why=why))
            continue
        seen.add(data['id'])
        to, where = data['to'], p.parent.name
        boxname = p.parent.parent.parent.name if where == 'done' else p.parent.parent.name
        if where == 'done':
            boxes[boxname]['done'] += 1
        else:
            counts = boxes[boxname]['inbox']
            counts[data['status']] = counts.get(data['status'], 0) + 1
        letters.append((data, to, where, at))
    resolved = {d.get('re') for d, _, _, _ in letters if d['status'] in ('DONE', 'BLOCKED', 'NEEDS-USER', 'FAILED')}
    opened = [dict(id=d['id'], **{'from': d['from']}, to=to, where=where, age_min=int((now - at).total_seconds() // 60)) for d, to, where, at in letters if d['status'] == 'REQUEST' and d['id'] not in resolved]
    return dict(v=1, open=sorted(opened, key=lambda x: (x['to'], x['id'])), boxes=boxes, bad=sorted(bad, key=lambda x: (x['file'], x['why'])))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('node', type=Path)
    ap.add_argument('--now', required=True)
    a = ap.parse_args()
    try:
        now = time(a.now)
    except ValueError:
        return 2
    if not a.node.is_dir():
        return 2
    print(json.dumps(summarize(a.node, now)))
    return 0
